import argparse, json, time, subprocess, hashlib, sys
from pathlib import Path

POLICY_PATH_DEFAULT = r"D:\AIOS\_agent-hub\policy\model-policy.v1.yaml"
ALERT_PATH = r"D:\AIOS\_agent-hub\policy\reconciler\alerts.jsonl"
DRIFT_PATH = r"D:\AIOS\_agent-hub\audit\drift-events.log"

def load_yaml(path):
    try:
        import yaml
        with open(path, "r", encoding="utf-8") as f:
            return yaml.safe_load(f)
    except Exception as e:
        print(f"FAIL load_policy: {e}", file=sys.stderr)
        return None

def scan_processes():
    proc_data = []
    try:
        out = subprocess.run(["wmic", "process", "get", "Name,ProcessId,CommandLine", "/FORMAT:CSV"],
                             capture_output=True, text=True, timeout=15)
        for line in out.stdout.splitlines()[1:]:
            parts = line.split(",", 2)
            if len(parts) >= 3:
                proc_data.append({"name": parts[0], "pid": parts[1], "cmdline": parts[2]})
    except Exception as e:
        proc_data.append({"error": str(e)})
    return proc_data

def scan_env():
    try:
        out = subprocess.run(["powershell", "-NoProfile", "-Command",
                              "Get-ChildItem env: | Where-Object { $_.Name -match 'OPENAI|ANTHROPIC|MiniMax|MODEL|API' } | ConvertTo-Json"],
                             capture_output=True, text=True, timeout=15)
        return json.loads(out.stdout) if out.stdout.strip() else []
    except Exception as e:
        return [{"error": str(e)}]

def check_compliance(policy, procs, envs):
    drift = []
    allowed = set(policy.get("model_policy", {}).get("allowed_providers", []))
    prohibited_keywords = ["deepseek", "qwen", "openai-gpt4", "anthropic-claude", "google-gemini"]
    for p in procs:
        cmd = (p.get("cmdline") or "").lower()
        name = (p.get("name") or "").lower()
        if not any(t in name for t in ("codex","claude","openclaw","hermes","node")):
            continue
        for kw in prohibited_keywords:
            if kw in cmd:
                drift.append({"type":"L2","source":"proc","name":name,"pid":p.get("pid"),"reason":f"prohibited_keyword:{kw}","cmd":cmd[:160]})
                break
    for e in envs:
        name = (e.get("Name") or "").upper()
        val = (e.get("Value") or "")
        if any(k in name for k in ("OPENAI_API_KEY","ANTHROPIC_API_KEY","MODEL_DEFAULT")):
            if "deepseek" in val.lower() or "openai.com" in val.lower() or "anthropic.com" in val.lower():
                if "MiniMax" not in val:
                    drift.append({"type":"L1","source":"env","name":name,"reason":"non_MiniMax_endpoint","value_prefix":val[:60]})
    return drift

def append_jsonl(path, obj):
    Path(path).parent.mkdir(parents=True, exist_ok=True)
    with open(path, "a", encoding="utf-8") as f:
        f.write(json.dumps(obj, ensure_ascii=False) + "\n")

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--policy", default=POLICY_PATH_DEFAULT)
    ap.add_argument("--once", action="store_true")
    args = ap.parse_args()
    policy = load_yaml(args.policy)
    if not policy:
        print("FATAL: cannot load policy", file=sys.stderr)
        sys.exit(2)
    procs = scan_processes()
    envs = scan_env()
    drift = check_compliance(policy, procs, envs)
    event = {"ts": time.time(), "policy_id": policy.get("policy_id"),
             "policy_version": policy.get("policy_version"),
             "proc_count": len(procs), "env_count": len(envs),
             "drift_count": len(drift), "drift": drift}
    append_jsonl(DRIFT_PATH, event)
    if drift:
        append_jsonl(ALERT_PATH, event)
        print(f"ALERT: {len(drift)} drift(s) → {ALERT_PATH}")
        sys.exit(1)
    print(f"OK: {len(procs)} procs / {len(envs)} env / 0 drift")

if __name__ == "__main__":
    main()
